window.kbPageData["views/entry/k-d8021c15125f1324"] = {"key":"entry/k-d8021c15125f1324","state":{"route":"entry/k-d8021c15125f1324"},"node":{"id":"k-d8021c15125f1324","mode":"k","title":"一事不再罚款","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["行政处罚中的一事不再罚款原则"],"qs":["江苏 2024 B类 行测#14"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"行政机关对同一当事人的同一个违法行为不得给予两次以上罚款。一个行为违反多个法律规范且均应罚款的，按罚款数额高的规定处罚。","review":{"definition":"行政机关对同一当事人的同一个违法行为不得给予两次以上罚款。一个行为违反多个法律规范且均应罚款的，按罚款数额高的规定处罚。","explanation":"许某因无证牌驾驶被罚款300元，因醉驾被吊销驾驶证。吊销属于另一处罚种类，这组处理没有重复给予行政罚款，B成立。行政罚款能否折抵刑事罚金另看刑事裁判是否把受罚事实作为同一事实处理。与题情高度相近的卢某检察指导性案例中，无证驾驶无号牌摩托车的300元罚款已折抵危险驾驶罪的罚金，因此A所称“不能折抵”过于绝对。","references":[{"source":"web-eb26c0179fff99a1","location":"第二十九条、第三十五条","quote":"应当折抵相应罚金"},{"source":"web-114c4f41d02daa49","location":"基本案情，刑事判决结果","quote":"300元罚款已折抵"}],"evidence":"交警部门对许某的不同行为作出不同的处罚","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 B类 行测#14":{"paper":"江苏 2024 B类 行测","n":14,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",5],"card":"ee2a90fcbcdd8389d4a598ca","links":[{"id":"k-d8021c15125f1324","role":"直接考查","why":"应按具体违法行为判断是否重复罚款，对不同违法行为分别处罚符合该规则。"}]}},"terms":{},"references":{"web-eb26c0179fff99a1":{"name":"《中华人民共和国行政处罚法》（2021年修订）","url":"https://cqca.miit.gov.cn/zwgk/zcwj/flfg/art/2022/art_07cd94bd65954d0aa8120e978088907f.html"},"web-114c4f41d02daa49":{"name":"《卢某诉福建省某市公安局交警支队道路交通行政处罚检察监督案》","url":"https://xzyl.jsjc.gov.cn/zt/dxal/202204/t20220426_417343.shtml"}},"topics":[],"units":{"k-d8021c15125f1324":[["江苏 2024 B类 行测#14"]]}};
